Q = [

# ===== ENV-121 氟氯烴管理辦法 =====
(L1,"第1條",1,"氟氯烴-法源",
 "氟氯烴管理辦法之訂定法源依據為何？",
 ["依空氣污染防制法第三十一條第二項規定訂定之","依空氣污染防制法第二十四條第三項規定訂定之","依蒙特婁議定書第五條第二項授權事項訂定之","依溫室氣體減量及管理法第十條規定授權訂定"],"a",
 "第1條：本辦法依空氣污染防制法第三十一條第二項規定訂定之。第2條定義氟氯烴為蒙特婁議定書列管化學物質附件Ｃ第一類物質，並經中央主管機關公告者，包括原生、回收或再生形態之化合物或混合物。第23條規定本辦法自發布日施行。",
 "What is the legal basis for the Regulations for the Management of HCFCs?",
 ["Adopted under Article 31, Paragraph 2 of the Air Pollution Control Act","Adopted under Article 24, Paragraph 3 of the Air Pollution Control Act","Adopted under Article 5, Paragraph 2 of the Montreal Protocol mandate","Adopted under Article 10 of the Greenhouse Gas Reduction and Management Act"],
 "Article 1; see also Articles 2 and 23."),

(L1,"第2條",2,"氟氯烴-定義",
 "本辦法所稱氟氯烴之生產量，其計算方式為何？",
 ["國內製造量減製程中回收或轉製成其他化學物質數量，再減依議定書認可技術銷毀之數量","國內製造量加輸入量減輸出量後，再加計製程中回收轉製成其他化學物質之全部數量","國內製造量加上回收再利用數量後，減去該年度輸出至國外之總數量所得之淨值","國內製造量減輸入量加輸出量，再加計依議定書認可技術所銷毀之數量之總和"],"a",
 "第2條第3款：生產量指國內製造量減去製程中回收或轉製成其他化學物質之數量，再減去依蒙特婁議定書認可技術所銷毀之數量所得之淨值；回收再利用之數量不視為生產量。同條第4款：消費量指生產量加輸入量減輸出量後之淨值，不含議定書決議通過之豁免用途數量。",
 "How is the production volume of HCFCs calculated under these Regulations?",
 ["Domestic manufacture minus amounts recovered or transformed in process, minus amounts destroyed by approved technology","Domestic manufacture plus imports minus exports, then adding back all amounts recovered and transformed in the process","Domestic manufacture plus the recycled and reused amounts, minus the total amount exported abroad in that year","Domestic manufacture minus imports plus exports, plus the amounts destroyed by technology approved under the Protocol"],
 "Article 2, Subparagraphs 3 and 4."),

(L1,"第2條",2,"氟氯烴-定義",
 "本辦法對回收、回用及ODP公噸之定義，下列敘述何者正確？",
 ["回收指自機具設備或容器中收集貯存；回用指經過濾乾燥等基礎純化後再使用；ODP公噸為破壞潛勢與重量公噸之乘值","回收指經過濾乾燥後再使用；回用指自機具設備中收集貯存之行為；ODP公噸為破壞潛勢與重量公噸之相除值","回收指銷毀報廢之行為；回用指轉製成其他化學物質之行為；ODP公噸為破壞潛勢加上重量公噸之相加值","回收指輸出至國外處理；回用指購入他廠回收品再販售；ODP公噸指重量公噸除以臭氧層破壞潛勢之商數"],"a",
 "第2條第9款、第10款：回收指自機具、設備或包裝容器中收集與貯存氟氯烴之行為；回用指將回收之氟氯烴經過濾、乾燥等基礎純化程序後再使用。同條第5款：ODP公噸指列管化學物質之臭氧層破壞潛勢與其重量公噸之乘值。",
 "Which statement correctly states the definitions of recovery, reuse and ODP tonnes?",
 ["Recovery is collecting and storing from equipment or containers; reuse is using again after filtering and drying; ODP tonne is potential times tonnes","Recovery is using again after filtering and drying; reuse is collecting and storing from equipment; ODP tonne is potential divided by tonnes","Recovery is destruction and scrapping; reuse is transformation into other chemicals; ODP tonne is potential added to weight in tonnes","Recovery is exporting abroad for treatment; reuse is buying and reselling others' recovered goods; ODP tonne is tonnes divided by potential"],
 "Article 2, Subparagraphs 5, 9 and 10."),

(L1,"第3條",3,"氟氯烴-消費量管制",
 "氟氯烴消費量之基準量及管制時程為何？",
 ["基準量六三八．一五六ODP公噸；一百零九年起每年不得超過基準量百分之○．五即三．一九一ODP公噸","基準量三一九．一五六ODP公噸；一百零九年起每年不得超過基準量百分之五即一五．九五八ODP公噸","基準量六三八．一五六ODP公噸；一百零五年起每年不得超過基準量百分之十即六三．八一六ODP公噸","基準量一二七六．三一二ODP公噸；一百十九年起每年不得超過基準量百分之一即一二．七六ODP公噸"],"a",
 "第3條：氟氯烴消費量之基準量為六三八．一五六ODP公噸；自一百零九年一月一日起每年不得超過基準量之百分之○．五，即三．一九一ODP公噸，並僅限供使用中之冷凍空調設備維修所需；自一百十九年一月一日起消費量為零。",
 "What is the baseline and control schedule for HCFC consumption?",
 ["Baseline 638.156 ODP tonnes; from 2020 no more than 0.5 percent of baseline, that is 3.191 ODP tonnes","Baseline 319.156 ODP tonnes; from 2020 no more than 5 percent of the baseline, that is 15.958 ODP tonnes","Baseline 638.156 ODP tonnes; from 2016 no more than 10 percent of the baseline, that is 63.816 ODP tonnes","Baseline 1276.312 ODP tonnes; from 2030 no more than 1 percent of the baseline, that is 12.76 ODP tonnes"],
 "Article 3."),

(L1,"第3條",2,"氟氯烴-消費量管制",
 "依本辦法，自中華民國一百十九年一月一日起氟氯烴消費量之規定，以及一百零九年起核配之限定用途為何？",
 ["消費量為零；一百零九年起核配數量僅限供使用中之冷凍空調設備維修所需","消費量減半；一百零九年起核配數量僅限供新建工程之冷媒初次填充所需","消費量為零；一百零九年起核配數量僅限供發泡劑及清洗溶劑製程使用所需","消費量維持基準量百分之○．五；並得供噴霧推進劑及新設備冷媒填充使用"],"a",
 "第3條第2項第2款：自一百十九年一月一日起，氟氯烴消費量為零；第1款規定一百零九年起之數量僅限供使用中之冷凍空調設備維修所需。第6條並自一百零九年一月一日起禁止新生產設備及新建工程之冷媒填充等使用氟氯烴。",
 "From 1 January 2030, what is the HCFC consumption limit, and what use is allowed from 2020?",
 ["Consumption is zero; from 2020 the quota may only serve servicing of in-use refrigeration and air conditioning equipment","Consumption is halved; from 2020 the quota may only serve first refrigerant charging of newly built projects","Consumption is zero; from 2020 the quota may only serve foam blowing agents and cleaning solvent processes","Consumption stays at 0.5 percent of baseline and may also serve aerosol propellants and new equipment charging"],
 "Article 3, Paragraph 2; see also Article 6."),

(L1,"第4條",2,"氟氯烴-生產量管制",
 "製造氟氯烴之供應廠商應於何時提報生產計畫？計畫應包括哪些內容？",
 ["每年一月、七月底前提報上、下半年生產計畫，包括製造量、供應轉製成其他化學物質之用量及輸出量","每年三月、九月底前提報上、下半年生產計畫，包括製造量、銷售對象名單及庫存量之增減情形","每年十月底前提報下年度全年生產計畫，包括製造量、回收量及員工人數等基本資料","每年四月、十月底前提報上、下半年生產計畫，包括輸入量、銷毀量及經銷商之名單資料"],"a",
 "第4條第3項：製造氟氯烴之供應廠商應於每年一月、七月底前向中央主管機關提報該年度上、下半年生產計畫，其生產計畫包括製造量、供應轉製成其他化學物質之用量及輸出量。同條第1項：生產量基準量亦為六三八．一五六ODP公噸。",
 "When must an HCFC-manufacturing supplier submit its production plan, and what must it contain?",
 ["By the end of January and July for each half year, covering manufactured volume, volume supplied for transformation, and exports","By the end of March and September for each half year, covering manufactured volume, customer lists, and changes in stock","By the end of October for the whole following year, covering manufactured volume, recovered volume, and staff numbers","By the end of April and October for each half year, covering imports, destroyed volume, and the list of distributors"],
 "Article 4, Paragraph 3."),

(L1,"第5條",1,"氟氯烴-輸出入",
 "氟氯烴之輸出入受何種限制？",
 ["未經許可不得輸入，且輸出入限向遵守蒙特婁議定書並經中央主管機關公告之國家或地區為之","未經許可不得輸出，輸入則不受限制，得向任何與我國有貿易往來之國家或地區為之","經地方主管機關備查即得輸入，輸出入國家或地區由財政部關務署逐案公告認定之","僅輸出須經許可，輸入限向已批准京都議定書並經經濟部公告之國家或地區為之"],"a",
 "第5條：氟氯烴未經許可不得輸入；其輸出、輸入限向遵守蒙特婁議定書規定並經中央主管機關公告之國家或地區為之。第19條對含氟氯烴產品或設備亦有相同之輸出入限制。",
 "What restrictions apply to the import and export of HCFCs?",
 ["Import requires a permit, and trade is limited to countries or areas complying with the Protocol and announced by the central authority","Export requires a permit while import is unrestricted and may be with any country or area having trade relations with Taiwan","A filing with the local competent authority suffices for import, and eligible countries are announced case by case by Customs","Only export needs a permit, and trade is limited to countries that ratified the Kyoto Protocol as announced by the Ministry"],
 "Article 5; see also Article 19."),

(L1,"第6條",3,"氟氯烴-用途管制",
 "氟氯烴禁止作為發泡劑及溶劑用途之管制時程分別自何時起？",
 ["發泡劑自一百零五年一月一日起禁止；溶劑（含生產及清洗製程）自一百零九年一月一日起禁止","發泡劑自一百零九年一月一日起禁止；溶劑（含生產及清洗製程）自一百十九年一月一日起禁止","發泡劑自九十九年一月一日起禁止；溶劑（含生產及清洗製程）自一百零三年一月一日起禁止","發泡劑自一百十九年一月一日起禁止；溶劑（含生產及清洗製程）自一百零五年一月一日起禁止"],"a",
 "第6條第1項第1款、第2款：自一百零五年一月一日起禁止使用氟氯烴作為發泡劑用途；自一百零九年一月一日起禁止作為溶劑（含生產及清洗製程）用途。同條第2項：中央主管機關應於禁止使用管制時程起，停止核發核配量予管制用途之使用廠商。",
 "From when are HCFCs banned as foam blowing agents and as solvents?",
 ["Foam blowing agents banned from 1 January 2016; solvents including production and cleaning banned from 1 January 2020","Foam blowing agents banned from 1 January 2020; solvents including production and cleaning banned from 1 January 2030","Foam blowing agents banned from 1 January 2010; solvents including production and cleaning banned from 1 January 2014","Foam blowing agents banned from 1 January 2030; solvents including production and cleaning banned from 1 January 2016"],
 "Article 6, Paragraph 1, Subparagraphs 1 and 2."),

(L1,"第6條",2,"氟氯烴-用途管制",
 "氟氯烴用於噴霧推進劑，以及用於新生產設備及新建工程冷媒填充，其禁用起始日各為何？",
 ["噴霧推進劑自九十九年一月一日起禁止；新設備及新建工程冷媒填充自一百零九年一月一日起禁止","噴霧推進劑自一百零九年一月一日起禁止；新設備及新建工程冷媒填充自九十九年一月一日起禁止","噴霧推進劑自一百零五年一月一日起禁止；新設備及新建工程冷媒填充自一百十九年一月一日起禁止","噴霧推進劑自一百零三年十月二十三日起禁止；新設備及新建工程冷媒填充自一百零五年一月一日起禁止"],"a",
 "第6條第1項第4款：自九十九年一月一日起禁止使用氟氯烴於噴霧推進劑用途；第3款：自一百零九年一月一日起禁止新生產設備及新建工程之冷媒填充等使用氟氯烴。違反者依第21條除依本法第六十八條處罰外，並得扣減核配量。",
 "From when are HCFCs banned as aerosol propellants and for charging new equipment and new construction projects?",
 ["Aerosol propellants banned from 1 January 2010; charging of new equipment and new projects banned from 1 January 2020","Aerosol propellants banned from 1 January 2020; charging of new equipment and new projects banned from 1 January 2010","Aerosol propellants banned from 1 January 2016; charging of new equipment and new projects banned from 1 January 2030","Aerosol propellants banned from 23 October 2014; charging of new equipment and new projects banned from 1 January 2016"],
 "Article 6, Paragraph 1, Subparagraphs 3 and 4; see also Article 21."),

(L1,"第7條",2,"氟氯烴-核配資格",
 "新增之氟氯烴使用廠商與供應廠商申請核配資格，應於何時提出？應檢具之實績文件為何？",
 ["應於七月底前提出，並檢具當年度一月至六月執行實績或其他可供查證之實績證明文件","應於十月底前提出，並檢具前一年度全年執行實績或其他可供查證之實績證明文件","應於一月底前提出，並檢具前一年度下半年執行實績或其他可供查證之實績證明文件","應於四月底前提出，並檢具當年度第一季執行實績或其他可供查證之實績證明文件"],"a",
 "第7條第1項：自一百零三年十月二十三日起，新增之使用廠商與供應廠商應於七月底前檢具商業登記證明、工廠登記證明、當年度一月至六月執行實績或其他可供查證之實績證明文件等，向中央主管機關申請核配資格。第9條並以該實績乘以二作為新申請者之核配量計算基準。",
 "By when must a new HCFC user or supplier apply for quota eligibility, and what performance document is required?",
 ["By the end of July, attaching the January to June performance of the current year or other verifiable supporting documents","By the end of October, attaching the full-year performance of the previous year or other verifiable supporting documents","By the end of January, attaching the second-half performance of the previous year or other verifiable supporting documents","By the end of April, attaching the first-quarter performance of the current year or other verifiable supporting documents"],
 "Article 7, Paragraph 1; see also Article 9."),

(L1,"第7條",2,"氟氯烴-核配資格",
 "取得核配資格廠商變更名稱地址負責人，以及連續二年度執行實績為零者，應如何處理？",
 ["變更者檢附變更後文件報請備查免重新申請；連續二年度實績為零者由中央主管機關取消核配資格","變更者應重新申請核配資格；連續二年度實績為零者僅減半核配量並得繼續保有核配資格","變更者由中央主管機關逕行註銷資格；連續三年度實績為零者始取消其核配資格並停止申請","變更者應於次年七月底前重新申請；連續一年度實績為零者即取消核配資格並不得再申請"],"a",
 "第7條第3項：取得核配資格之廠商變更公司或工廠名稱、地址、負責人者，檢附變更後之登記證明文件報請中央主管機關備查，免重新申請核配資格。同條第4項：連續二年度執行實績為零之廠商，中央主管機關應取消其核配資格，重新申請時應依第1項規定辦理。",
 "How are changes of name or address, and two consecutive years of zero performance, handled for quota holders?",
 ["Changes only need documents filed for record without reapplying; two consecutive years of zero performance ends the eligibility","Changes require a fresh eligibility application; two consecutive years of zero performance only halves the quota granted","Changes cause the authority to revoke eligibility directly; only three consecutive years of zero performance ends eligibility","Changes require reapplication by the end of July next year; one year of zero performance ends eligibility permanently"],
 "Article 7, Paragraphs 3 and 4."),

(L1,"第8條",3,"氟氯烴-核配總量",
 "中央主管機關得保留當年度氟氯烴消費量上限值之多少比例？保留供何用途？剩餘數量如何核配？",
 ["得保留百分之十供國家建設、國防軍事及緊急處理所需；剩餘依輸入實績比例核配予供應廠商","得保留百分之三十供國家建設、國防軍事及緊急處理所需；剩餘依製造實績比例核配予使用廠商","得保留百分之五供學術研究、實驗分析及緊急處理所需；剩餘依銷售實績比例平均核配予經銷商","得保留百分之二十供國家建設及環境保護研究所需；剩餘依庫存量比例優先核配予輸入廠商"],"a",
 "第8條第1項：中央主管機關得保留當年度消費量上限值之百分之十，供國家建設、國防軍事及緊急處理之所需。同條第2項：經保留後之消費量作為該年度核配總量，優先核配予具核配資格之使用廠商，剩餘數量依輸入實績之比例核配予供應廠商。",
 "What share of the annual HCFC consumption cap may the central authority reserve, for what, and how is the remainder allocated?",
 ["Ten percent may be reserved for national construction, defense and emergencies; the rest goes to suppliers by import performance","Thirty percent may be reserved for national construction, defense and emergencies; the rest goes to users by manufacturing record","Five percent may be reserved for academic research, analysis and emergencies; the rest is split evenly among all distributors","Twenty percent may be reserved for national construction and environmental research; the rest goes to importers by stock levels"],
 "Article 8, Paragraphs 1 and 2."),

(L1,"第9條",3,"氟氯烴-核配量計算",
 "中央主管機關核定下年度全年核配量之期限，以及既有核配資格廠商之計算基準為何？",
 ["每年十月底前核定；以前一年度下半年與當年度上半年執行實績總和，並以不超過一百十三年核配量為限","每年七月底前核定；以前一年度全年執行實績總和計算，並以不超過一百零九年核配量之二倍為限","每年十二月底前核定；以當年度一月至六月執行實績乘以二計算，並以不超過基準量百分之五為限","每年四月底前核定；以前三年度執行實績之平均值計算，並以不超過一百十三年核配量之半數為限"],"a",
 "第9條第1項、第2項第1款：中央主管機關應於每年十月底前核定受核配廠商下年度之全年核配量；既有核配資格廠商以前一年度下半年與當年度上半年執行實績之總和為基準，並以不超過該廠商一百十三年核配量為限。",
 "By when is next year's annual quota approved, and how is it computed for existing eligible enterprises?",
 ["By the end of October; the sum of last year's second half and this year's first half, capped at the firm's 2024 quota","By the end of July; the sum of the previous full year's performance, capped at twice the firm's 2020 allocated quota","By the end of December; the January to June performance multiplied by two, capped at five percent of the baseline","By the end of April; the average performance of the previous three years, capped at half of the firm's 2024 quota"],
 "Article 9, Paragraphs 1 and 2."),

(L1,"第9條",2,"氟氯烴-核配量計算",
 "新申請核配資格廠商之核配量計算基準，以及額外核配量之計算基準各為何？",
 ["新申請者以當年度一月至六月執行實績乘以二；額外核配量以上年度全年可查證之回收量為基準","新申請者以當年度一月至六月執行實績乘以三；額外核配量以上年度全年之輸入放行量為基準","新申請者以前一年度下半年執行實績乘以二；額外核配量以當年度上半年之銷售實績為基準","新申請者以申請時之庫存量乘以二計算；額外核配量以該廠商前三年平均使用量為計算基準"],"a",
 "第9條第2項第2款：新申請核配資格廠商以當年度一月至六月執行實績乘以二為計算基準。同條第3項：額外核配量以上年度全年可查證之回收量為計算基準，中央主管機關得考量當年度國家消費量核配後之餘額，按比例酌予核配。",
 "How is the quota computed for newly eligible enterprises, and what is the basis for additional quota?",
 ["New applicants use January to June performance times two; additional quota is based on last year's verifiable recovered volume","New applicants use January to June performance times three; additional quota is based on last year's released import volume","New applicants use last year's second-half performance times two; additional quota is based on this year's first-half sales","New applicants use stock at application times two; additional quota is based on the firm's three-year average consumption"],
 "Article 9, Paragraphs 2 and 3."),

(L1,"第10條",2,"氟氯烴-豁免用途",
 "輸入經蒙特婁議定書決議通過豁免用途之氟氯烴，其申請與核定期限為何？",
 ["廠商應於每年一月、七月底前提出申請，中央主管機關應於每年四月、十月底前核定核可量","廠商應於每年四月、十月底前提出申請，中央主管機關應於每年一月、七月底前核定核可量","廠商應於每年七月底前一次提出申請，中央主管機關應於每年十二月底前核定其核可量","廠商應於輸入前三十日提出申請，中央主管機關應於受理後十五日內核定其核可量"],"a",
 "第10條：輸入經議定書決議通過豁免用途之氟氯烴，供應廠商或使用廠商應於每年一月、七月底前檢具申請書、政府機關核准登記設立證明、用途說明、無法替代原因說明、需求量說明及佐證資料等，向中央主管機關申請；中央主管機關應於每年四月、十月底前核定豁免用途輸入核可量。",
 "What are the application and approval deadlines for importing HCFCs for exempted uses?",
 ["Enterprises apply by the end of January and July; the central authority approves the volume by the end of April and October","Enterprises apply by the end of April and October; the central authority approves the volume by the end of January and July","Enterprises apply once by the end of July each year; the central authority approves the volume by the end of December","Enterprises apply thirty days before import; the central authority approves the volume within fifteen days of acceptance"],
 "Article 10."),

(L1,"第11條",3,"氟氯烴-輸入許可",
 "持有核配量之廠商未於當期輸入放行或提領，且未申請展延許可者，其核配量如何處理？",
 ["當期核配量或豁免用途輸入核可量由中央主管機關收回","當期核配量得自動遞延至次一期繼續使用不受影響限制","當期核配量由中央主管機關按未使用數量之兩倍加計扣減","當期核配量得由該廠商自行轉讓予其他具資格之使用廠商"],"a",
 "第11條第3項：貨品未於當期輸入放行或向國內採購提領，且未於當期結束前向中央主管機關申請展延許可者，其當期核配量或豁免用途輸入核可量由中央主管機關收回。同條第1項：持有核配量或豁免用途核可之廠商，須持核配許可文件始得申請核發輸入許可證，貨品限當期輸入。",
 "What happens to the quota if goods are not released or collected in the period and no extension is applied for?",
 ["The quota or exempted-use import approval for that period is taken back by the central competent authority","The quota for that period is automatically carried over to the next period and may still be used freely","The quota for that period is reduced by twice the unused amount as a penalty by the competent authority","The quota for that period may be transferred by the enterprise itself to any other eligible user firm"],
 "Article 11, Paragraphs 1 and 3."),

(L1,"第12條",3,"氟氯烴-核配量轉讓",
 "使用廠商與供應廠商就核配量之轉售或轉讓，規定有何不同？",
 ["使用廠商不得轉售或經銷，違反者取消核配資格；供應廠商經核准得互為轉讓，未經核准扣除兩倍轉讓量","使用廠商經核准得轉售或經銷，違反者扣減核配量；供應廠商一律不得轉讓，違反者逕行取消核配資格","使用廠商與供應廠商均得自由轉讓核配量，僅須於轉讓後三十日內報請中央主管機關備查即可","使用廠商得將核配量轉讓予供應廠商，供應廠商則僅得轉讓予經銷商，違反者處以罰鍰並公告名單"],"a",
 "第12條第1項：使用廠商不得將所持有之核配量再行轉售或從事經銷業務，違反者中央主管機關應取消其核配資格。同條第2項：供應廠商經核准得將核配量互為轉讓；未經核准轉讓者，得於該廠商全年實際核配量中扣除兩倍轉讓數量或取消其核配資格。",
 "How do the rules on transferring quotas differ between user enterprises and supplier enterprises?",
 ["Users may not resell or distribute, losing eligibility if they do; suppliers may transfer with approval, else twice that amount is cut","Users may resell with approval and only lose some quota if they breach; suppliers may never transfer and lose eligibility outright","Both users and suppliers may transfer quotas freely, provided the transfer is filed for record within thirty days after it","Users may transfer quotas to suppliers and suppliers only to distributors; breaches draw fines and public listing of names"],
 "Article 12, Paragraphs 1 and 2."),

(L1,"第13條",1,"氟氯烴-異動",
 "持有核配量之廠商，其貨品品名及數量有異動時應如何辦理？",
 ["應向中央主管機關申請核准後始得為之","應於異動後三十日內報請地方主管機關備查","得逕行辦理異動並於年度申報時一併敘明","應向財政部關務署申請變更輸入許可證內容"],"a",
 "第13條：持有核配量之廠商，其貨品品名及數量有異動者，應向中央主管機關申請核准。第11條並規定核配貨品限當期輸入或提領，未於當期使用且未展延者，核配量由中央主管機關收回。",
 "What must a quota holder do when the name or quantity of its goods changes?",
 ["It must apply to the central competent authority and obtain approval first","It must file the change for record with the local authority within thirty days","It may make the change directly and simply describe it in the annual report","It must apply to Customs Administration to amend the import permit content"],
 "Article 13; see also Article 11."),

(L1,"第14條",2,"氟氯烴-申報",
 "持有核配量之使用廠商及供應廠商，應於何時向中央主管機關申報執行實績？",
 ["應於每年一月、四月、七月、十月底前申報上一季之品名、數量、使用或銷售量及庫存量等資料","應於每年一月、七月底前申報上半年之品名、數量、使用或銷售量及庫存量等相關資料","應於每年三月底前一次申報前一年度之品名、數量、使用或銷售量及庫存量等資料","應於每次輸入或製造後十五日內申報該批之品名、數量、使用或銷售量及庫存量資料"],"a",
 "第14條第1項、第2項：持有核配量之使用廠商及供應廠商應於每年一月、四月、七月、十月底前，向中央主管機關申報上一季採購或輸入製造之氟氯烴品名、數量、使用量或銷售量、庫存量等資料，並檢具可查證之相關證明文件。",
 "When must quota-holding users and suppliers report their performance to the central authority?",
 ["By the end of January, April, July and October, reporting last quarter's names, volumes, use or sales, and stock","By the end of January and July, reporting the previous half year's names, volumes, use or sales, and stock","By the end of March once a year, reporting the previous full year's names, volumes, use or sales, and stock","Within fifteen days of each import or manufacture, reporting that batch's names, volumes, use or sales, and stock"],
 "Article 14, Paragraphs 1 and 2."),

(L1,"第14條",2,"氟氯烴-申報",
 "氟氯烴未申報、逾期申報或申報文件逾期未補正者，其法律效果為何？",
 ["未申報或逾期申報者該季執行實績視為零；申報文件逾期未補正者視為未申報","未申報或逾期申報者該季執行實績減半計算；申報文件逾期未補正者得再展延一次","未申報或逾期申報者僅通知限期補行申報；申報文件逾期未補正者由主管機關代為填具","未申報或逾期申報者取消其核配資格；申報文件逾期未補正者該季實績仍照常認列"],"a",
 "第14條第3項：未申報或逾期申報者，該季執行實績視為零。同條第5項：申報文件有欠缺或不合規定者，應於中央主管機關通知之期限內補正，逾期未補正者視為未申報。第7條並規定連續二年度執行實績為零者取消核配資格。",
 "What is the effect of failing to report, reporting late, or failing to cure a defective report in time?",
 ["Non-reporting or late reporting makes that quarter's performance zero; failure to cure a defect counts as not reporting","Non-reporting or late reporting halves that quarter's performance; a defective report may be granted one more extension","Non-reporting or late reporting only draws a notice to report within a period; the authority fills in defective reports","Non-reporting or late reporting cancels quota eligibility at once; a defective report still has its performance counted"],
 "Article 14, Paragraphs 3 and 5; see also Article 7."),

(L1,"第15條",2,"氟氯烴-販售管理",
 "關於氟氯烴之販售，本辦法有何規定？",
 ["供應廠商應申報經銷商名單等資料，僅供應廠商及所申報之經銷商得販售，販售紀錄保存五年","供應廠商應申報經銷商名單等資料，任何領有商業登記者均得販售，販售紀錄保存三年備查","供應廠商免申報經銷商資料，惟販售對象限具核配資格之使用廠商，販售紀錄保存一年備查","供應廠商應報請地方主管機關核准後始得販售，經銷商不須申報，販售紀錄保存十年備查"],"a",
 "第15條：供應廠商除申報各季執行實績外，並應申報其經銷商名單、基本資料、販售對象之用途說明及對應之銷售品名與數量；供應廠商及其申報之經銷商始得從事氟氯烴之販售；販售行為應作成紀錄，並保存五年備查。",
 "What does the regulation provide regarding the sale of HCFCs?",
 ["Suppliers must report their distributor list; only suppliers and reported distributors may sell; records are kept five years","Suppliers must report their distributor list, but anyone with business registration may sell; records are kept three years","Suppliers need not report distributors, but may only sell to quota-eligible users; records are kept one year for review","Suppliers must obtain local authority approval before selling, distributors need no report, and records are kept ten years"],
 "Article 15."),

(L1,"第16條",2,"氟氯烴-審查",
 "中央主管機關受理核配資格申請及執行實績申報事項，應於多久內完成審查？",
 ["應進行文件完整性及內容審查，並於受理截止日後九十日內完成審查","應進行文件完整性及內容審查，並於受理截止日後三十日內完成審查","應僅進行文件完整性之形式審查，並於收件日起十五日內完成審查","應進行文件完整性及內容審查，並於次年度一月底前完成全部審查"],"a",
 "第16條第1項：中央主管機關受理核配資格申請及執行實績申報事項，應進行文件完整性及內容之審查，並於受理截止日後九十日內完成審查。同條第2項：中央主管機關得遴聘相關政府機關代表及專家學者審查。",
 "Within what period must the central authority complete review of quota applications and performance reports?",
 ["It reviews completeness and content of documents and completes review within ninety days after the closing date","It reviews completeness and content of documents and completes review within thirty days after the closing date","It reviews only the formal completeness of documents and completes the review within fifteen days of receipt","It reviews completeness and content of documents and completes all reviews by the end of January next year"],
 "Article 16."),

(L1,"第17條",3,"氟氯烴-回收設備",
 "氟氯烴回收設備應具備之功能規範為何？何種情形得免使用回收或回用設備？",
 ["回收設備應能抽取後使設備或系統壓力降至一○二mmHg以下；現地回收作業空間無法放置者不在此限","回收設備應能抽取後使設備或系統壓力降至七六○mmHg以下；作業人員未取得證照者不在此限","回收設備應能抽取後使設備或系統壓力降至二○mmHg以下；填充量低於十公斤之作業不在此限","回收設備應能抽取後使設備或系統溫度降至零度以下；設備使用年限逾十年者不在此限之列"],"a",
 "第17條第1項：使用氟氯烴之填充、拆解、換裝作業應使用回收設備或回用設備，但現地回收作業空間無法放置回收設備者不在此限。同條第2項第1款：回收設備應具有抽取氟氯烴後，設備或系統壓力降至一○二mmHg以下之功能。",
 "What performance must HCFC recovery equipment meet, and when is such equipment not required?",
 ["It must draw down the equipment or system pressure to below 102 mmHg; on-site work with no room for the unit is exempt","It must draw down the equipment or system pressure to below 760 mmHg; work by uncertified operators is exempt","It must draw down the equipment or system pressure to below 20 mmHg; charging of less than ten kilograms is exempt","It must lower the equipment or system temperature below zero degrees; units older than ten years in use are exempt"],
 "Article 17, Paragraphs 1 and 2."),

(L1,"第17條",3,"氟氯烴-回用設備",
 "回用設備處理氟氯烴作為冷媒用途時，所含水分、潤滑油及空氣等不純物應分別低於多少濃度？",
 ["水分低於二○ppm、潤滑油低於百分之○．○一體積百分比、空氣低於百分之一．五體積百分比","水分低於二○○ppm、潤滑油低於百分之○．一體積百分比、空氣低於百分之十五體積百分比","水分低於二ppm、潤滑油低於百分之一．五體積百分比、空氣低於百分之○．○一體積百分比","水分低於一○二ppm、潤滑油低於百分之○．五體積百分比、空氣低於百分之五體積百分比"],"a",
 "第17條第2項第2款：回用設備應兼具回收設備功能，並可處理氟氯烴作為冷媒用途中所含水分、潤滑油及空氣等不純物，分別至低於二○ppm、百分之○．○一（體積百分比）及百分之一．五（體積百分比）之濃度。",
 "For reuse equipment, below what levels must moisture, lubricant and air impurities be reduced?",
 ["Moisture below 20 ppm, lubricant below 0.01 percent by volume, and air below 1.5 percent by volume","Moisture below 200 ppm, lubricant below 0.1 percent by volume, and air below 15 percent by volume","Moisture below 2 ppm, lubricant below 1.5 percent by volume, and air below 0.01 percent by volume","Moisture below 102 ppm, lubricant below 0.5 percent by volume, and air below 5 percent by volume"],
 "Article 17, Paragraph 2, Subparagraph 2."),

(L1,"第18條",2,"氟氯烴-作業措施",
 "使用回收設備或回用設備時，應採行之措施及紀錄保存年限為何？",
 ["填充前應檢測洩漏並先修復、回收容器標明氟氯烴種類、設備定期維護保養，紀錄保存五年備查","填充後應檢測洩漏並記錄結果、回收容器標示重量噸數、設備每月更換濾材，紀錄保存三年備查","填充前應報請主管機關核准、回收容器標明廠商名稱、設備每年校正一次，紀錄保存一年備查","填充前應通知經銷商到場會同、回收容器標明購入日期、設備使用滿五年報廢，紀錄免予保存"],"a",
 "第18條第1項：使用回收設備或回用設備應採行下列措施：填充前進行設備或系統洩漏檢測，發現洩漏應先予修復；回收容器應標明其裝置之氟氯烴種類；回收或回用設備應定期維護與保養。同條第2項：前項作業應作成紀錄，並保存五年備查。",
 "What measures apply when using recovery or reuse equipment, and how long must records be kept?",
 ["Leak testing and repair before charging, labelling the HCFC type on containers, regular maintenance; records kept five years","Leak testing after charging with results logged, labelling container tonnage, monthly filter change; records kept three years","Prior approval from the authority before charging, labelling the firm's name, annual calibration; records kept one year","Notifying the distributor to attend, labelling the purchase date, scrapping units after five years; no records required"],
 "Article 18."),

(L1,"第19條",1,"氟氯烴-產品輸入",
 "含氟氯烴產品或設備之輸出入，本辦法如何規範？",
 ["未經許可禁止輸入，且輸出入限向遵守蒙特婁議定書並經中央主管機關公告之國家或地區","未經許可禁止輸出，輸入則僅須向中央主管機關辦理備查即可，不限國家或地區之範圍","得自由輸出入，惟應於通關放行後三十日內向中央主管機關申報品名數量及來源國別","僅整機設備禁止輸入，其組件及含該組件之系統不受限制，得自任何國家或地區輸入"],"a",
 "第19條：含氟氯烴產品或設備未經許可禁止輸入；其輸出、輸入限向遵守蒙特婁議定書規定並經中央主管機關公告之國家或地區為之。第2條第2款並定義含氟氯烴產品或設備包括商品、組件及含該組件之系統。",
 "How does the regulation control import and export of products or equipment containing HCFCs?",
 ["Import without a permit is banned, and trade is limited to Protocol-complying countries announced by the central authority","Export without a permit is banned, while import only needs a filing with the central authority with no country limits","They may be traded freely, provided names, volumes and country of origin are reported within thirty days of release","Only complete equipment is banned from import; components and systems containing them may come from any country"],
 "Article 19; see also Article 2, Subparagraph 2."),

(L1,"第20條",3,"氟氯烴-違規處置",
 "擅自輸入氟氯烴或含氟氯烴產品設備者，其貨品應如何處置？相關費用由何人負擔？",
 ["尚未通關放行者應於關稅法規定期限內辦理退運；經沒入者以回收、變賣、銷毀等方式處理，費用由行為人負擔","尚未通關放行者一律逕予銷毀不得退運；經沒入者由中央主管機關標售，所得價金充作環境保護基金之收入","尚未通關放行者得於補辦許可後放行；經沒入者由海關逕行退運出口，相關費用由中央主管機關編列預算支應","尚未通關放行者應暫存於保稅倉庫滿一年；經沒入者移交國防部作為軍事用途，處置費用由輸入國之出口商負擔"],"a",
 "第20條：未依本辦法規定申請許可擅自輸入者，尚未通關放行之貨品應於關稅法規定之期限內辦理退運；違反輸入規定而經沒入之貨品，應以回收、再精製、回用、暫存、變賣、銷毀或其他適當方式處理；相關處置費用由違反輸入行為人負擔，並限期繳納。",
 "How are illegally imported HCFCs or HCFC-containing goods handled, and who bears the costs?",
 ["Goods not yet cleared must be re-exported within the Customs Act period; confiscated goods are recovered, sold or destroyed, at the violator's cost","Goods not yet cleared must all be destroyed without re-export; confiscated goods are auctioned by the authority for the environmental fund","Goods not yet cleared may be released after a permit is obtained; confiscated goods are re-exported by Customs at the authority's budget cost","Goods not yet cleared are stored in a bonded warehouse for a year; confiscated goods go to the military at the foreign exporter's cost"],
 "Article 20."),

(L1,"第21條",2,"氟氯烴-罰則",
 "違反氟氯烴管制用途規定者，除依空氣污染防制法處罰外，中央主管機關另得為何種處分？",
 ["得扣減其核配量，必要時並得取消核配資格，且於一年內停止其核配資格之申請","得扣減其核配量，必要時並得取消核配資格，且於三年內停止其核配資格之申請","得命其停工停業並限期改善，屆期未改善者按次處罰並公告該廠商之名稱資料","得沒入其全部庫存氟氯烴並移送法辦，另處以核配量兩倍價額之代金及利息"],"a",
 "第21條：違反第六條第一項管制用途規定者，除依本法第六十八條規定處罰外，中央主管機關得扣減其核配量；必要時，並得取消其核配資格，且於一年內停止其核配資格之申請。第6條第1項所列為發泡劑、溶劑、新設備冷媒填充及噴霧推進劑等管制用途。",
 "Besides penalties under the Air Pollution Control Act, what may the central authority impose for breach of use controls?",
 ["It may cut the quota and, if necessary, revoke eligibility and bar reapplication for one year","It may cut the quota and, if necessary, revoke eligibility and bar reapplication for three years","It may order suspension of work and improvement, with repeated fines and public naming of the firm","It may confiscate all stock and refer for prosecution, plus charge twice the quota value with interest"],
 "Article 21; see also Article 6, Paragraph 1."),

(L1,"第22條",1,"氟氯烴-文書格式",
 "本辦法所定相關文書格式，由何機關定之？",
 ["由中央主管機關定之","由直轄市及縣市主管機關定之","由財政部關務署會商定之","由各目的事業主管機關定之"],"a",
 "第22條：本辦法所定相關文書格式，由中央主管機關定之。第16條並規定中央主管機關受理核配資格申請及執行實績申報，應於受理截止日後九十日內完成審查，並得遴聘相關政府機關代表及專家學者審查。",
 "Which authority prescribes the document formats required by these Regulations?",
 ["The central competent authority prescribes them","The municipal and county competent authorities do","The Customs Administration jointly prescribes them","Each relevant industry regulator prescribes them"],
 "Article 22; see also Article 16."),

(L1,"第23條",1,"氟氯烴-施行",
 "氟氯烴管理辦法之施行日期規定為何？",
 ["本辦法自發布日起施行","本辦法自發布後六個月施行","本辦法自一百十九年元旦施行","本辦法自發布後一年施行之"],"a",
 "第23條：本辦法自發布日施行。本辦法之管制時程另定於第3條、第4條及第6條，例如消費量與生產量自一百零九年一月一日起不得超過基準量之百分之○．五，自一百十九年一月一日起為零。",
 "When do these Regulations take effect?",
 ["They take effect on the date of promulgation","They take effect six months after promulgation","They take effect on 1 January 2030","They take effect one year after promulgation"],
 "Article 23; see also Articles 3, 4 and 6."),

# ===== ENV-122 玻璃業空氣污染物排放標準 =====
(L2,"第1條",1,"玻璃業標準-法源",
 "玻璃業空氣污染物排放標準之訂定法源依據為何？",
 ["依空氣污染防制法第二十條第二項規定訂定之","依空氣污染防制法第三十一條第二項規定訂定之","依固定污染源設置與操作許可證管理辦法訂定","依空氣污染防制法第十四條第三項規定訂定之"],"a",
 "第1條：本標準依空氣污染防制法第二十條第二項規定訂定之。第4條規定玻璃業空氣污染物排放標準規定值如附表；第7條規定本標準除另定施行日期者外，自發布日施行。",
 "What is the legal basis for the Glass Industry Air Pollutant Emission Standards?",
 ["Adopted under Article 20, Paragraph 2 of the Air Pollution Control Act","Adopted under Article 31, Paragraph 2 of the Air Pollution Control Act","Adopted under the Regulations on Stationary Source Permit Management","Adopted under Article 14, Paragraph 3 of the Air Pollution Control Act"],
 "Article 1; see also Articles 4 and 7."),

(L2,"第2條",2,"玻璃業標準-適用範圍",
 "玻璃業空氣污染物排放標準之適用對象為何？",
 ["平板玻璃、玻璃纖維、容器玻璃、玻璃基板、影像管、光學、色版、燈罩等玻璃製造用熔融爐","僅平板玻璃及容器玻璃之熔融爐，玻璃纖維及玻璃基板製造設備則不在本標準適用範圍之內","玻璃製造業之全部製程設備，包括原料倉儲、輸送帶、切裁研磨及包裝出貨等作業設施","僅適用於年產量一百公噸以上之玻璃製造廠，其他小型玻璃熔融爐由地方主管機關另定"],"a",
 "第2條：本標準適用於平板玻璃、玻璃纖維、容器玻璃、玻璃基板、影像管、光學、色版、燈罩、電器用玻璃、水玻璃、玻璃釉料及其他玻璃製造用熔融爐。第6條並就二以上既存熔融爐合由同一排放管道排放者另設規定。",
 "To what does the Glass Industry Air Pollutant Emission Standards apply?",
 ["Melting furnaces making flat glass, glass fibre, container glass, substrates, tubes, optical, colour plate and lampshade glass","Only melting furnaces for flat glass and container glass, with glass fibre and substrate equipment excluded from the standards","All process equipment of glass manufacturers, including raw material storage, conveyors, cutting, grinding and packaging","Only glass plants with annual output of one hundred tonnes or more, smaller furnaces being set by local authorities"],
 "Article 2; see also Article 6."),

(L2,"第3條",3,"玻璃業標準-定義",
 "本標準所稱純氧助燃及富氧分段燃燒，其定義各為何？",
 ["純氧助燃指助燃氣體含氧量大於或等於百分之九十之燃燒方式；富氧分段燃燒指降低爐內第一階段進氣量並於後端通入富氧空氣完成第二階段完全燃燒","純氧助燃指助燃氣體含氧量大於或等於百分之二十一之燃燒方式；富氧分段燃燒指提高爐內第一階段進氣量並於前端通入純氧完成第二階段之完全燃燒","純氧助燃指排氣含氧量大於或等於百分之十五之燃燒方式；富氧分段燃燒指將熔融爐分為二座並各自通入富氧空氣完成兩階段之完全燃燒作業方式","純氧助燃指以電力加熱取代燃料燃燒之方式；富氧分段燃燒指於排放管道末端注入純氧使未燃物完成二次燃燒之空氣污染防制作業方式"],"a",
 "第3條第3款、第4款：純氧助燃指助燃氣體含氧量大於或等於百分之九十之燃燒方式；富氧分段燃燒指降低熔融爐內第一階段燃燒進氣量，並在熔融爐後端通入富氧空氣，完成第二階段完全燃燒之分段燃燒方式。第5條就此二種燃燒方式另定氮氧化物之計算基準。",
 "How are pure-oxygen combustion and oxygen-enriched staged combustion defined in these standards?",
 ["Pure-oxygen combustion uses combustion gas with oxygen of 90 percent or more; staged combustion cuts first-stage air and adds enriched air at the rear for complete second-stage burning","Pure-oxygen combustion uses combustion gas with oxygen of 21 percent or more; staged combustion raises first-stage air and adds pure oxygen at the front for complete second-stage burning","Pure-oxygen combustion means exhaust oxygen of 15 percent or more; staged combustion splits the furnace into two units each fed with enriched air for two-stage complete burning","Pure-oxygen combustion means electric heating replacing fuel burning; staged combustion injects pure oxygen at the stack end so unburned matter is burned a second time"],
 "Article 3, Subparagraphs 3 and 4; see also Article 5."),

(L2,"第3條",2,"玻璃業標準-定義",
 "本標準所稱新設熔融爐與既存熔融爐，其區分基準為何？",
 ["新設者指自一百零三年十一月十四日起設立；既存者指該日前已完成建造、建造中或已完成招標訂約者","新設者指自一百零九年九月十七日起設立；既存者指該日前已完成建造、建造中或已完成招標訂約者","新設者指自一百零三年十一月十四日起取得操作許可證；既存者指該日前已取得設置許可證而尚未建造者","新設者指自本標準發布日起五年內設立；既存者指設立逾五年並持續操作而未辦理任何變更登記之爐體"],"a",
 "第3條第1款、第2款：新設熔融爐指自一百零三年十一月十四日起設立之熔融爐；既存熔融爐指該日前已完成建造、建造中、完成工程招標程序或未經招標程序已訂立工程施作契約者，但既存熔融爐符合固定污染源設置與操作許可證管理辦法第三條規定之變更條件者，以新設熔融爐論。",
 "How are new and existing melting furnaces distinguished under these standards?",
 ["New ones are established from 14 November 2014; existing ones were built, under construction or already contracted before that date","New ones are established from 17 September 2020; existing ones were built, under construction or already contracted before that date","New ones obtained an operating permit from 14 November 2014; existing ones held a setup permit before that date but were unbuilt","New ones are established within five years of promulgation; existing ones have operated over five years without any registered change"],
 "Article 3, Subparagraphs 1 and 2."),

(L2,"第4條",1,"玻璃業標準-規定值",
 "玻璃業空氣污染物排放標準之規定值，係以何種方式定之？",
 ["排放標準規定值列於本標準之附表，依附表所定數值管制","排放標準規定值列於本標準第五條之計算公式中直接規範","排放標準規定值由各直轄市縣市主管機關視地區狀況另訂","排放標準規定值依固定污染源操作許可證所載數值個別認定"],"a",
 "第4條：玻璃業空氣污染物排放標準規定值如附表。第5條並規定濃度計算以凱氏溫度二百七十三度及一大氣壓下未經稀釋之乾燥排氣體積為計算基準，並以排氣含氧量百分之十五為參考基準。",
 "How are the emission limit values of the Glass Industry standards prescribed?",
 ["The limit values are set out in the appended table of the standards and controlled accordingly","The limit values are prescribed directly within the calculation formulas of Article 5","The limit values are separately set by each municipal or county authority by locality","The limit values are determined case by case as stated in the stationary source permit"],
 "Article 4; see also Article 5."),

(L2,"第5條",3,"玻璃業標準-濃度計算",
 "玻璃業空氣污染物濃度計算之基準為何？其含氧參考基準之例外情形為何？",
 ["以凱氏溫度二百七十三度及一大氣壓未稀釋乾燥排氣為基準，含氧參考基準百分之十五；用電力、純氧助燃及富氧分段燃燒者以實測含氧值為參考","以凱氏溫度二百七十三度及一大氣壓未稀釋濕排氣為基準，含氧參考基準百分之十八；用電力、純氧助燃及富氧分段燃燒者以百分之六為參考基準","以攝氏二十五度及一大氣壓經稀釋之乾燥排氣為基準，含氧參考基準百分之十一；用電力、純氧助燃及富氧分段燃燒者以百分之二十為參考基準值","以凱氏溫度二百七十三度及一大氣壓未稀釋乾燥排氣為基準，含氧參考基準百分之六；用電力、純氧助燃及富氧分段燃燒者免計算污染物濃度值"],"a",
 "第5條第1項：本標準各種污染物之濃度計算，均以凱氏溫度二百七十三度及一大氣壓下未經稀釋之乾燥排氣體積為計算基準，除使用電力、純氧助燃及富氧分段燃燒者以未經稀釋之排氣含氧實測值為參考基準外，並以排氣含氧量百分之十五為參考基準。校正公式為 C＝(21-15)/(21-Os)×Cs。",
 "What is the basis for calculating pollutant concentrations, and what is the exception on the oxygen reference?",
 ["Dry undiluted exhaust at 273 K and one atmosphere, oxygen reference 15 percent; electric, pure-oxygen and staged combustion use the measured oxygen value","Wet undiluted exhaust at 273 K and one atmosphere, oxygen reference 18 percent; electric, pure-oxygen and staged combustion use 6 percent as reference","Diluted dry exhaust at 25 degrees Celsius and one atmosphere, oxygen reference 11 percent; electric, pure-oxygen and staged combustion use 20 percent","Dry undiluted exhaust at 273 K and one atmosphere, oxygen reference 6 percent; electric, pure-oxygen and staged combustion need not calculate concentrations"],
 "Article 5, Paragraph 1."),

(L2,"第5條",3,"玻璃業標準-EF計算",
 "使用電力、純氧助燃及富氧分段燃燒者，其氮氧化物排放標準以EF表示，EF之計算公式及單位為何？",
 ["EF＝Eh／As，即檢測期間氮氧化物排放量（kg/hr）除以熔融玻璃量（ton/hr），單位為公斤／公噸","EF＝As／Eh，即檢測期間熔融玻璃量（ton/hr）除以氮氧化物排放量（kg/hr），單位為公噸／公斤","EF＝Eh×As，即檢測期間氮氧化物排放量（kg/hr）乘以熔融玻璃量（ton/hr），單位為公斤小時","EF＝Cs／Os，即實測污染物濃度除以排氣含氧實測百分率，單位為每百分點之百萬分之一濃度"],"a",
 "第5條第3項：使用電力、純氧助燃及富氧分段燃燒者，氮氧化物排放標準依 EF＝Eh／As 計算。第3條第9至11款：EF為熔融爐生產每公噸熔融玻璃量之氮氧化物排放量（kg/ton）；Eh為檢測期間之氮氧化物排放量（kg/hr）；As為檢測期間之熔融玻璃量（ton/hr）。",
 "For electric, pure-oxygen and staged combustion, how is the NOx emission factor EF calculated?",
 ["EF = Eh / As, that is NOx emitted during testing (kg/hr) divided by molten glass output (ton/hr), in kilograms per tonne","EF = As / Eh, that is molten glass output during testing (ton/hr) divided by NOx emitted (kg/hr), in tonnes per kilogram","EF = Eh × As, that is NOx emitted during testing (kg/hr) multiplied by molten glass output (ton/hr), in kilogram hours","EF = Cs / Os, that is measured pollutant concentration divided by measured exhaust oxygen percentage, per percentage point"],
 "Article 5, Paragraph 3; see also Article 3, Subparagraphs 9 to 11."),

(L2,"第6條",2,"玻璃業標準-合併排放",
 "二以上既存熔融爐合由同一排放管道排放空氣污染物時，其氮氧化物排放標準如何適用？",
 ["任一既存熔融爐屬純氧助燃者，其氮氧化物排放適用純氧助燃之排放標準","應依各爐之熔融玻璃量加權平均，分別計算後取其中最寬鬆之排放標準","應全部適用新設熔融爐之排放標準，不得再主張既存熔融爐之寬限規定","任一既存熔融爐屬純氧助燃者，該管道即免受氮氧化物排放標準之管制"],"a",
 "第6條：二以上既存熔融爐合由同一排放管道排放空氣污染物，任一既存熔融爐屬純氧助燃者，其氮氧化物排放適用純氧助燃之排放標準。第3條第3款：純氧助燃指助燃氣體含氧量大於或等於百分之九十之燃燒方式。",
 "When two or more existing furnaces share one stack, how does the NOx standard apply?",
 ["If any existing furnace uses pure-oxygen combustion, the pure-oxygen NOx emission standard applies to the discharge","The limits are weighted by each furnace's molten glass output and the most lenient resulting standard is used","All of them must comply with the standard for new furnaces and may no longer claim existing-furnace treatment","If any existing furnace uses pure-oxygen combustion, that stack is exempt from NOx emission standards entirely"],
 "Article 6; see also Article 3, Subparagraph 3."),

(L2,"第7條",1,"玻璃業標準-施行",
 "玻璃業空氣污染物排放標準之施行日期規定為何？",
 ["本標準除另定施行日期者外，自發布日施行","本標準一律自發布後屆滿一年之日起施行","本標準除另定者外，自發布後六個月施行","本標準自中央主管機關另行公告之日施行"],"a",
 "第7條：本標準除另定施行日期者外，自發布日施行。第3條並以一百零三年十一月十四日作為新設與既存熔融爐之區分基準日。",
 "When do the Glass Industry Air Pollutant Emission Standards take effect?",
 ["They take effect on the date of promulgation unless another date is set","They uniformly take effect one year after the date of promulgation","Unless otherwise provided they take effect six months after promulgation","They take effect on a date separately announced by the central authority"],
 "Article 7; see also Article 3."),

# ===== ENV-131 陶瓷業空氣污染物排放標準 =====
(L3,"第1條",1,"陶瓷業標準-法源",
 "陶瓷業空氣污染物排放標準之訂定法源依據為何？",
 ["依空氣污染防制法第二十條第二項規定訂定之","依空氣污染防制法第二十四條第一項規定訂定","依固定污染源設置操作及燃料使用許可證辦法訂定","依空氣污染防制法第三十四條第二項規定訂定之"],"a",
 "第1條：本標準依空氣污染防制法第二十條第二項規定訂定之。第4條規定本標準規定值如附表；第6條規定本標準除另定施行日期者外，自發布日施行。",
 "What is the legal basis for the Ceramics Industry Air Pollutant Emission Standards?",
 ["Adopted under Article 20, Paragraph 2 of the Air Pollution Control Act","Adopted under Article 24, Paragraph 1 of the Air Pollution Control Act","Adopted under the Regulations on Stationary Source Setup and Fuel Permits","Adopted under Article 34, Paragraph 2 of the Air Pollution Control Act"],
 "Article 1; see also Articles 4 and 6."),

(L3,"第2條",2,"陶瓷業標準-適用對象",
 "陶瓷業空氣污染物排放標準之適用對象及排除規定為何？",
 ["適用陶瓷業之噴霧乾燥塔、烘乾設備及燒成窯，但產品總設計或實際年產量小於一百公噸者除外","適用陶瓷業之噴霧乾燥塔、烘乾設備及燒成窯，但產品總設計或實際年產量小於一千公噸者除外","適用陶瓷業全廠所有製程設備及原料堆置場，但年營業額低於一百萬元之工廠不在適用之列","適用陶瓷業之燒成窯及釉藥調配設備，但使用電力加熱且無燃料燃燒之設備不在適用之列"],"a",
 "第2條：本標準之適用對象指陶瓷業之噴霧乾燥塔、烘乾設備及燒成窯；但產品總設計或實際年產量小於一百公噸者，不在此限。第3條並就噴霧乾燥塔、烘乾設備及燒成窯分別定義。",
 "What does the Ceramics Industry standard apply to, and what is excluded?",
 ["It applies to spray dryers, drying equipment and firing kilns, excluding plants with designed or actual output under 100 tonnes a year","It applies to spray dryers, drying equipment and firing kilns, excluding plants with designed or actual output under 1000 tonnes a year","It applies to all process equipment and raw material yards of ceramics plants, excluding those with turnover below one million","It applies to firing kilns and glaze preparation equipment, excluding electrically heated equipment that burns no fuel at all"],
 "Article 2; see also Article 3."),

(L3,"第3條",2,"陶瓷業標準-定義",
 "本標準對噴霧乾燥塔、烘乾設備及燒成窯之定義，下列敘述何者正確？",
 ["噴霧乾燥塔指含水分泥漿霧化後與大量熱空氣接觸之設備；烘乾設備指移除已成型坯胎水分之設備；燒成窯指將含水製坯燒成成品之設備","噴霧乾燥塔指移除已成型坯胎水分之設備；烘乾設備指將含水製坯燒成成品之設備；燒成窯指含水分泥漿霧化後與熱空氣接觸之設備","噴霧乾燥塔指將釉藥噴塗於坯體表面之設備；烘乾設備指將成品冷卻至常溫之設備；燒成窯指將原料研磨混合成泥漿之調配設備裝置","噴霧乾燥塔指以水霧洗滌廢氣之防制設備；烘乾設備指將回收粉塵乾燥再利用之設備；燒成窯指以電力加熱進行退火處理之熱處理設備"],"a",
 "第3條第3至5款：噴霧乾燥塔指將含有水分之泥漿經霧化後與大量熱空氣接觸之設備；烘乾設備指將已成型坯胎中水分移除之設備；燒成窯指將含有水分之製坯予以燒成成品之設備。第2條規定此三者為本標準之適用對象。",
 "Which statement correctly gives the definitions of spray dryer, drying equipment and firing kiln?",
 ["Spray dryer atomizes wet slurry into contact with hot air; drying equipment removes water from formed bodies; firing kiln fires wet bodies into products","Spray dryer removes water from formed bodies; drying equipment fires wet bodies into products; firing kiln atomizes wet slurry into hot air contact","Spray dryer sprays glaze onto body surfaces; drying equipment cools products to room temperature; firing kiln grinds and mixes raw materials into slurry","Spray dryer is a wet scrubber for exhaust gas; drying equipment dries recovered dust for reuse; firing kiln is electric heat-treating equipment for annealing"],
 "Article 3, Subparagraphs 3 to 5; see also Article 2."),

(L3,"第3條",2,"陶瓷業標準-符號",
 "本標準所定符號C、Cs及Os之意義為何？Os超過多少時應以該上限計算？",
 ["C為經校正或依法免校正之排放濃度；Cs為依所定方法測得之濃度；Os為排氣含氧實測百分率，超過百分之二十以百分之二十計","C為依所定方法測得之濃度；Cs為經校正後之排放濃度；Os為排氣含氧實測百分率，超過百分之十八以百分之十八計","C為排放標準之規定值上限；Cs為實際排放之質量流率；Os為燃料含硫百分率之實測值，超過百分之五以百分之五計","C為經稀釋後之排放濃度值；Cs為未經稀釋之排放濃度；Os為排氣含水率之實測百分率，超過百分之二十以百分之十計"],"a",
 "第3條第6至8款：C指經校正或依法令不需校正之污染物排放濃度；Cs指依中央主管機關所定測定方法測得之污染物排放濃度；Os指排氣中含氧百分率之實測值，如超過百分之二十，則以百分之二十計算之。第5條之校正公式為 C＝(21-18)/(21-Os)×Cs。",
 "What do the symbols C, Cs and Os mean, and what cap applies to Os?",
 ["C is the corrected or exempt concentration; Cs is the measured concentration; Os is measured exhaust oxygen, capped at 20 percent","C is the measured concentration; Cs is the corrected concentration; Os is measured exhaust oxygen, capped at 18 percent","C is the upper limit set by the standard; Cs is the actual mass flow rate; Os is measured fuel sulphur, capped at 5 percent","C is the diluted concentration value; Cs is the undiluted concentration; Os is measured exhaust moisture, capped at 10 percent"],
 "Article 3, Subparagraphs 6 to 8; see also Article 5."),

(L3,"第4條",1,"陶瓷業標準-規定值",
 "陶瓷業空氣污染物排放標準之規定值，係以何種方式呈現？",
 ["本標準之規定值列於附表，依附表所定數值管制排放","本標準之規定值直接列於條文之中逐項明定管制數值","本標準之規定值授權各地方主管機關依區域特性另訂","本標準之規定值由業者於操作許可證申請時自行提報"],"a",
 "第4條：本標準規定值如附表。第5條規定濃度計算以凱氏溫度二百七十三度及一大氣壓下未經稀釋之乾燥排氣體積為計算基準，並以排氣含氧量百分之十八為參考基準。",
 "How are the emission limit values of the Ceramics Industry standards presented?",
 ["The limit values are set out in the appended table and control emissions accordingly","The limit values are listed item by item directly in the text of the articles","The limit values are delegated to local authorities to set by regional character","The limit values are proposed by operators themselves when applying for permits"],
 "Article 4; see also Article 5."),

(L3,"第5條",3,"陶瓷業標準-濃度校正",
 "陶瓷業空氣污染物濃度計算之基準溫度、壓力及含氧參考基準為何？",
 ["以凱氏溫度二百七十三度及一大氣壓下未經稀釋之乾燥排氣體積為基準，並以排氣含氧量百分之十八為參考基準","以凱氏溫度二百七十三度及一大氣壓下未經稀釋之乾燥排氣體積為基準，並以排氣含氧量百分之十五為參考基準","以攝氏二十五度及一大氣壓下經稀釋後之濕排氣體積為計算基準，並以排氣含氧量百分之六為參考基準值","以凱氏溫度二百九十八度及二大氣壓下未經稀釋之乾燥排氣體積為基準，並以排氣含氧量百分之十一為參考"],"a",
 "第5條：本標準各項污染物之濃度計算，均以凱氏溫度二百七十三度及一大氣壓下未經稀釋之乾燥排氣體積為計算基準，並以排氣含氧量百分之十八為參考基準，校正公式為 C＝(21-18)/(21-Os)×Cs。第3條第8款：Os超過百分之二十者以百分之二十計算。",
 "What temperature, pressure and oxygen reference basis apply to ceramics concentration calculations?",
 ["Dry undiluted exhaust volume at 273 K and one atmosphere, with an exhaust oxygen reference of 18 percent","Dry undiluted exhaust volume at 273 K and one atmosphere, with an exhaust oxygen reference of 15 percent","Diluted wet exhaust volume at 25 degrees Celsius and one atmosphere, with an oxygen reference of 6 percent","Dry undiluted exhaust volume at 298 K and two atmospheres, with an exhaust oxygen reference of 11 percent"],
 "Article 5; see also Article 3, Subparagraph 8."),

(L3,"第6條",1,"陶瓷業標準-施行",
 "陶瓷業空氣污染物排放標準之施行日期規定為何？",
 ["本標準除另定施行日期者外，自發布日施行","本標準自發布後屆滿六個月之日起正式施行","本標準除另定者外，自次年一月一日開始施行","本標準自各地方主管機關公告實施之日施行之"],"a",
 "第6條：本標準除另定施行日期者外，自發布日施行。第3條第1款、第2款並以本標準發布日作為新設污染源與既存污染源之區分基準。",
 "When do the Ceramics Industry Air Pollutant Emission Standards take effect?",
 ["They take effect on the date of promulgation unless another date is set","They take effect upon expiry of six months from the date of promulgation","Unless otherwise provided they take effect on 1 January of the next year","They take effect on the date announced by each local competent authority"],
 "Article 6; see also Article 3."),
]
